 	return status;
 }

+static int unlock_region(struct panthor_device *ptdev, u32 as_nr)
+{
+	return write_cmd(ptdev, as_nr, AS_COMMAND_UNLOCK);
+}
+
 static void lock_region(struct panthor_device *ptdev, u32 as_nr,
