+static struct attribute *si4455_attributes[] = {
+	&dev_attr_package_size.attr,
+	&dev_attr_rx_channel.attr,
+	&dev_attr_tx_channel.attr,
+	&dev_attr_tx_timeout.attr,
+	&dev_attr_current_rssi.attr,
+	NULL
+};
