 	struct v4l2_pix_format_mplane *fmt = &f->fmt.pix_mp;
@@ -178,5 +502,16 @@ void rkvdec_hevc_run_preamble(struct rkvdec_ctx *ctx,
 			      V4L2_CID_STATELESS_HEVC_SCALING_MATRIX);
